"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[5753],{28453:(e,n,t)=>{t.d(n,{R:()=>a,x:()=>r});var i=t(96540);const s={},o=i.createContext(s);function a(e){const n=i.useContext(o);return i.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(o.Provider,{value:n},e.children)}},54746:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>h,contentTitle:()=>r,default:()=>g,frontMatter:()=>a,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"qiangguo/engineeringthinking","title":"","description":"Since the forum won\'t allow posts about poetry, this young lady will switch to chatting about so-called science-and-engineering thinking. According to some people, the defining characteristic of science-and-engineering thinking is \\"how things are\\" and \\"how to do things.\\" Due to space constraints, let us first discuss only \\"how things are.\\" \\"How things are\\" has its prerequisites: 1. How is the \\"how\\" in \\"how things are\\"? 2. Can this \\"how\\" be grasped? 3. What \\"is\\" the \\"how\\"? 4. How does the \\"how\\" \\"be\\"? 5. What exactly is the nature of that which grasps \\"how things are\\"? And so on. Do these questions have ready-made answers? In a certain sense, no -- they remain matters of endless debate. For example, question 2 alone consumed Kant\'s entire life\'s effort and he merely touched the edge; question 3 is the problem Heidegger agonized over.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/engineeringthinking.md","sourceDirName":"qiangguo","slug":"/qiangguo/engineeringthinking","permalink":"/qiangguo/engineeringthinking","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"engineeringthinking","title":"","hide_table_of_contents":true},"sidebar":"qiangguoSidebar","previous":{"title":"\u6cd5\u5f8b\u7684\u975e\u9053\u5fb7\u5316\u662f\u4eba\u7c7b\u5386\u53f2\u4e2d\u5177\u6709\u5212\u65f6\u4ee3\u610f\u4e49\u7684\u5de8\u5927\u8fdb\u6b65","permalink":"/qiangguo/nonmoralization"},"next":{"title":"\u4f55\u65b0\uff0c\u4e0d\u8981\u4ee5\u8001\u5356\u8001\uff0c\u4ee5\u65e0\u77e5\u5356\u65e0\u77e5\uff01","permalink":"/qiangguo/oldforold"}}');var s=t(74848),o=t(28453);const a={id:"engineeringthinking",title:"",hide_table_of_contents:!0},r="So-Called Science-and-Engineering Thinking Is Merely a Variant of Theological Thinking",h={},l=[];function c(e){const n={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"so-called-science-and-engineering-thinking-is-merely-a-variant-of-theological-thinking",children:"So-Called Science-and-Engineering Thinking Is Merely a Variant of Theological Thinking"})}),"\n",(0,s.jsx)(n.p,{children:'Since the forum won\'t allow posts about poetry, this young lady will switch to chatting about so-called science-and-engineering thinking. According to some people, the defining characteristic of science-and-engineering thinking is "how things are" and "how to do things." Due to space constraints, let us first discuss only "how things are." "How things are" has its prerequisites: 1. How is the "how" in "how things are"? 2. Can this "how" be grasped? 3. What "is" the "how"? 4. How does the "how" "be"? 5. What exactly is the nature of that which grasps "how things are"? And so on. Do these questions have ready-made answers? In a certain sense, no -- they remain matters of endless debate. For example, question 2 alone consumed Kant\'s entire life\'s effort and he merely touched the edge; question 3 is the problem Heidegger agonized over.'}),"\n",(0,s.jsx)(n.p,{children:"This young lady does not intend to delve deeper into this issue, as it would exceed the scope of this forum. Godel's theorem tells us that perfection and completeness cannot be had simultaneously -- no closed so-called complete system can contain perfection. And an ant's thinking, however expansive, is still an ant's thinking. From this, what can everyone grasp?"}),"\n",(0,s.jsx)(n.p,{children:'Today, let us pursue question 5 above further: what exactly is the nature of that which grasps "how things are"? Why is this question important? Because even if question 1 -- "how is the \'how\' in \'how things are\'?" -- had a linear, singular answer, meaning: the "how" of "how things are" is completely and strictly independent of the "being" that grasps "how things are," even in this scenario, different "beings" that grasp "how things are" would still derive different "hows" from the same "how things are." When these differences form different equivalence classes according to some relation, what emerges ranges from differing opinions to differing classes and other variations of wildly different intensity.'}),"\n",(0,s.jsx)(n.p,{children:'Now, let us look at what "how things are" actually is from a simpler angle. First, all instances of "how things are" belong to different levels and are seen through different refractive indices. This means issues similar to "an ant\'s thinking, however expansive, is still an ant\'s thinking" exist. Second, even at the same level and same refractive index, one must assume that from the moment of seeing "how things are" to the moment of acting on "how things are," the relationship with respect to time is linear, with no singularities in between -- but does this assumption necessarily hold? Furthermore, as the uncertainty principle implies, the premise that the "how" of "how things are" is completely and strictly independent of the "being" that grasps "how things are" may not exist at all. Similar problems are too numerous to continue here.'}),"\n",(0,s.jsx)(n.p,{children:"So-called science-and-engineering thinking is merely a variant of theological thinking. Laughably, some people think these two are different -- it is merely that in some cases the divine is humanized, and in others it is hidden. Without sufficient understanding of this point, one merely continues to spin one's own cocoon. How could one possibly glimpse that different blue sky?"})]})}function g(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}}}]);